134	        this.ownerMapper = ownerMapper;
135	        this.petMapper = petMapper;
136	        this.visitMapper = visitMapper;
137	    }
138	
139	    /**
140	     * Normalise a raw telephone number to E.164 form.
141	     *
142	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
143	     * code are kept when present; otherwise country code '+61' is assumed and a
144	     * single leading '0' is dropped from the national digits. The result must have
145	     * between 8 and 15 digits after the '+'.
146	     *
147	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
148	     * national-number length is additionally validated against that country code:
149	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
150	     * length is wrong for its country is rejected.
151	     *
152	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
153	     */
154	    static String toE164(String raw) {
155	        if (raw == null) {
156	            return null;
157	        }
158	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
159	        String digits;
160	        boolean explicitCountryCode;
161	        if (cleaned.startsWith("+")) {
162	            digits = cleaned.substring(1);
163	            explicitCountryCode = true;
164	        } else {
165	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
166	            digits = "61" + national;
167	            explicitCountryCode = false;
168	        }
169	        if (!digits.matches("[0-9]{8,15}")) {
170	            return null;
171	        }
172	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
173	            return null;
174	        }
175	        return "+" + digits;
176	    }
177	
178	    /**
179	     * Validate the national-number length of an E.164 number (its digits without the
180	     * leading '+') against the requirement for its country code: country code '+61'
181	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
182	     * without a configured length requirement are accepted unchanged.
183	     */
184	    private static boolean hasValidNationalLength(String digits) {
185	        if (digits.startsWith("61")) {
186	            return digits.length() - "61".length() == 9;
187	        }
188	        if (digits.startsWith("1")) {
189	            return digits.length() - "1".length() == 10;
190	        }
191	        return true;
192	    }
193	
194	    /**
195	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
196	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
197	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
198	     * input normalises to the empty string.
199	     */
200	    private static String normaliseIdentity(String value) {
201	        if (value == null) {
202	            return "";
203	        }
204	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
205	    }
206	
207	    /**
208	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
209	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
210	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
211	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
212	     * that is both stored and used for every address comparison.
213	     */
214	    static String normaliseAddress(String value) {
215	        if (value == null) {
216	            return "";
217	        }
218	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
219	        if (collapsed.isEmpty()) {
220	            return "";
221	        }
222	        String[] tokens = collapsed.split(" ");
223	        StringBuilder result = new StringBuilder();
224	        for (int i = 0; i < tokens.length; i++) {
225	            if (i > 0) {
226	                result.append(' ');
227	            }
228	            result.append(expandAddressAbbreviation(tokens[i]));
229	        }
230	        return result.toString();
231	    }
232	
233	    /**
234	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
235	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
236	     * returned unchanged.
237	     */
238	    private static String expandAddressAbbreviation(String token) {
239	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
240	        return switch (core) {
241	            case "ST" -> "STREET";
242	            case "RD" -> "ROAD";
243	            case "AVE" -> "AVENUE";
244	            default -> token;
245	        };
246	    }
247	
248	    /**
249	     * Derive the stable, shared household identifier for owners in the same household: the first 12
250	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
251	     * so every owner with the same last name and postcode resolves to the same value regardless of
252	     * the order in which they were created.
253	     */
254	    private static String householdId(String lastNameKey, String postcode) {
255	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
256	    }
257	
258	    /**
259	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
260	     * name and postcode). An owner without a postcode has no household peers and counts as a household
261	     * of one.
262	     */
263	    private int householdSize(Owner owner) {
264	        if (owner.getPostcode() == null) {
265	            return 1;
266	        }
267	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
268	        return (int) this.clinicService.findAllOwners().stream()
269	            .filter(existing -> existing.getPostcode() != null
270	                && householdId.equals(
271	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
272	            .count();
273	    }
274	
275	    /**
276	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
277	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
278	     * postcode has no household peers, so this is empty.
279	     */
280	    private List<Owner> otherHouseholdMembers(Owner owner) {
281	        if (owner.getPostcode() == null) {
282	            return List.of();
283	        }
284	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
285	        return this.clinicService.findAllOwners().stream()
286	            .filter(existing -> !existing.isDeleted())
287	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
288	            .filter(existing -> existing.getPostcode() != null
289	                && householdId.equals(
290	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
291	            .toList();
292	    }
293	
294	    /**
295	     * The owner's membership level after applying the household ceiling: the natural level derived
296	     * from the owner's membership points, capped at one above the current maximum membership level
297	     * among the owner's existing household members. With no existing household member no cap applies.
298	     * Assumes the owner's household size has already been populated.
299	     */
300	    private Integer cappedMembershipLevel(Owner owner) {
301	        Integer natural = ownerMapper.formatMembershipLevel(owner);
302	        if (natural == null) {
303	            return null;
304	        }
305	        List<Owner> members = otherHouseholdMembers(owner);
306	        if (members.isEmpty()) {
307	            return natural;
308	        }
309	        int maxMemberLevel = 0;
310	        for (Owner member : members) {
311	            member.setHouseholdSize(householdSize(member));
312	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
313	            if (memberLevel != null) {
314	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
315	            }
316	        }
317	        return Math.min(natural, maxMemberLevel + 1);
318	    }
319	
320	    /**
321	     * Build the unified member id for a new owner as {@code '<REGION><FY><HASH8><CHK>'}, where REGION is
322	     * the region code derived from the postcode (falling back to the city-to-region table, else
323	     * {@code "UNKNOWN"}), FY is the two-digit fiscal year (starting 1 July) of the
324	     * business-day-adjusted {@code registrationDate}, HASH8 is the first 8 upper-case hex characters of
325	     * the SHA-256 digest over {@code normalizedTelephone + lastName}, and CHK is a single Luhn check
326	     * digit computed over the digits of {@code '<REGION><FY><HASH8>'}. The id depends only on the
327	     * owner's own region, fiscal year and identity, not on how many owners already exist.
328	     */
329	    private String nextMemberId(String region, LocalDate registrationDate,
330	                                String normalizedTelephone, String lastName) {
331	        String fiscalYear = String.format("%02d", fiscalYearStart(registrationDate) % 100);
332	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
333	        String base = region + fiscalYear + hash8;
334	        return base + luhnCheckDigit(base);
335	    }
336	
337	    /**
338	     * De-duplicate a computed member id against the ids already assigned to existing owners: when
339	     * {@code memberId} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
340	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
341	     */
342	    private String deduplicateMemberId(String memberId) {
343	        Set<String> existing = this.clinicService.findAllOwners().stream()
344	            .map(Owner::getMemberId)
345	            .filter(Objects::nonNull)
346	            .collect(Collectors.toSet());
347	        if (!existing.contains(memberId)) {
348	            return memberId;
349	        }
350	        int n = 2;
351	        while (existing.contains(memberId + "-" + n)) {
352	            n++;
353	        }
354	        return memberId + "-" + n;
355	    }
356	
357	    /**
358	     * The starting calendar year of the fiscal year (which starts on 1 July) that contains the given
359	     * date: the date's own year when it falls on or after 1 July, otherwise the previous year.
360	     */
361	    private static int fiscalYearStart(LocalDate date) {
362	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
363	    }
364	
365	    /**
366	     * A single Luhn check digit (0-9) computed over the digits contained in {@code input}
367	     * (non-digit characters are ignored).
368	     */
369	    private static int luhnCheckDigit(String input) {
370	        int sum = 0;
371	        boolean dbl = true;
372	        for (int i = input.length() - 1; i >= 0; i--) {
373	            char c = input.charAt(i);
374	            if (c < '0' || c > '9') {
375	                continue;
376	            }
377	            int d = c - '0';
378	            if (dbl) {
379	                d *= 2;
380	                if (d > 9) {
381	                    d -= 9;
382	                }
383	            }
384	            sum += d;
385	            dbl = !dbl;
386	        }
387	        return (10 - (sum % 10)) % 10;
388	    }
389	
390	    /**
391	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
392	     */
393	    private static String hash8(String input) {
394	        return hashHex(input, 8, true);
395	    }
396	
397	    /**
398	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
399	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
400	     */
401	    private static String hashHex(String input, int length, boolean upperCase) {
402	        try {
403	            byte[] digest = MessageDigest.getInstance("SHA-256")
404	                .digest(input.getBytes(StandardCharsets.UTF_8));
405	            StringBuilder sb = new StringBuilder(digest.length * 2);
406	            for (byte b : digest) {
407	                sb.append(String.format("%02x", b));
408	            }
409	            String hex = sb.substring(0, length);
410	            return upperCase ? hex.toUpperCase() : hex;
411	        }
412	        catch (java.security.NoSuchAlgorithmException e) {
413	            throw new IllegalStateException(e);
414	        }
415	    }
416	
417	    /**
418	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
419	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
420	     * fixed city-to-region table, else {@code "UNKNOWN"}.
421	     */
422	    private static String region(String postcode, String city) {
423	        String fromPostcode = regionForPostcode(postcode);
424	        return fromPostcode != null ? fromPostcode : regionForCity(city);
425	    }
426	
427	    /**
428	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
429	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
430	     */
431	    private static String regionForPostcode(String postcode) {
432	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
433	            return null;
434	        }
435	        int value = Integer.parseInt(postcode);
436	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
437	            int[] range = entry.getValue();
438	            if (value >= range[0] && value <= range[1]) {
439	                return entry.getKey();
440	            }
441	        }
442	        return null;
443	    }
444	
445	    /**
446	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
447	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
448	     * weekday; ordinary weekday dates are returned unchanged.
449	     */
450	    static LocalDate toBusinessDay(LocalDate date) {
451	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
452	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
453	            || PUBLIC_HOLIDAYS.contains(date)) {
454	            date = date.plusDays(1);
455	        }
456	        return date;
457	    }
458	
459	    /**
460	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
461	     * using the same per-day accumulation path as the daily create-limit rule.
462	     */
463	    private long ownersCreatedOn(LocalDate registrationDate) {
464	        LocalDate day = toBusinessDay(registrationDate);
465	        return this.clinicService.findAllOwners().stream()
466	            .map(Owner::getRegistrationDate)
467	            .filter(existing -> existing != null)
468	            .map(OwnerRestControllerV1::toBusinessDay)
469	            .filter(day::equals)
470	            .count();
471	    }
472	
473	    /**
474	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
475	     * postcode against the owner's city region.
476	     */
477	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
478	        "NSW", new int[] {2000, 2099},
479	        "VIC", new int[] {3000, 3099},
480	        "QLD", new int[] {4000, 4099});
481	
482	    /**
483	     * Resolve an owner's region from the city using the fixed city-to-region table
484	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
485	     * when the city is not listed.
486	     */
487	    private static String regionForCity(String city) {
488	        return switch (city == null ? "" : city) {
489	            case "Sydney" -> "NSW";
490	            case "Melbourne" -> "VIC";
491	            case "Brisbane" -> "QLD";
492	            default -> "UNKNOWN";
493	        };
494	    }
495	
496	    /**
497	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
498	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
499	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
500	     */
501	    private static boolean isPostcodeValid(String postcode, String city) {
502	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
503	            return false;
504	        }
505	        int[] range = REGION_POSTCODES.get(regionForCity(city));
506	        if (range == null) {
507	            return true;
508	        }
509	        int value = Integer.parseInt(postcode);
510	        return value >= range[0] && value <= range[1];
511	    }
512	
513	    /**
514	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
515	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
516	     */
517	    private static boolean isDisposableEmailDomain(String email) {
518	        if (email == null) {
519	            return false;
520	        }
521	        int at = email.lastIndexOf('@');
522	        if (at < 0 || at == email.length() - 1) {
523	            return false;
524	        }
525	        String domain = email.substring(at + 1).toLowerCase();
526	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
527	    }
528	
529	    /**
530	     * Whether the owner's city is approaching the per-city capacity limit of 50 owners: true when the
531	     * city already holds between 40 and 49 owners (counted the same way as the hard-limit rule, over
532	     * all owners with a matching, normalized city), otherwise false.
533	     */
534	    private boolean capacityWarning(String city) {
535	        String cityKey = normaliseIdentity(city);
536	        long ownersInCity = this.clinicService.findAllOwners().stream()
537	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
538	            .count();
539	        return ownersInCity >= 40 && ownersInCity <= 49;
540	    }
