573	
574	    /**
575	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
576	     * request carries no such header (or there is no active servlet request). A blank value is treated
577	     * as absent.
578	     */
579	    private static String currentIdempotencyKey() {
580	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
581	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
582	            return null;
583	        }
584	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
585	        return (key == null || key.isBlank()) ? null : key;
586	    }
