588	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
589	    @Override
590	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
591	        String idempotencyKey = currentIdempotencyKey();
592	        if (idempotencyKey != null) {
593	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
594	            if (existingId != null) {
595	                Owner existing = this.clinicService.findOwnerById(existingId);
596	                if (existing != null) {
597	                    existing.setHouseholdSize(householdSize(existing));
598	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
599	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
600	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
601	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
602	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
603	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
604	                }
605	            }
606	        }
607	        String telephone = toE164(ownerFieldsDto.getTelephone());
608	        if (telephone == null) {
609	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
610	        }
611	        String email = ownerFieldsDto.getEmail();
612	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
613	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
614	        }
615	        if (isDisposableEmailDomain(email)) {
616	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
617	        }
618	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
619	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
620	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
621	        // normalized addressLine2 appended after a single space when present.
622	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
623	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
624	        boolean structuredAddress = !addressLine1.isEmpty();
625	        String address;
626	        if (structuredAddress) {
627	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
628	        } else {
629	            address = normaliseAddress(ownerFieldsDto.getAddress());
630	        }
631	        if (address.isEmpty()) {
632	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
633	        }
634	        String postcode = ownerFieldsDto.getPostcode();
635	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
636	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
637	        }
638	        if (ownerFieldsDto.getRegistrationDate() != null
639	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
640	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
641	        }
642	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
643	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
644	        LocalDate registrationDate = toBusinessDay(effectiveDate);
645	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
646	            .map(Owner::getRegistrationDate)
647	            .filter(existing -> existing != null)
648	            .map(OwnerRestControllerV1::toBusinessDay)
649	            .filter(registrationDate::equals)
650	            .count();
651	        if (ownersCreatedThatDay >= 100) {
652	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
653	        }
654	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
655	        long ownersInCity = this.clinicService.findAllOwners().stream()
656	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
657	            .count();
658	        if (ownersInCity >= 50) {
659	            return new ResponseEntity<>(HttpStatus.CONFLICT);
660	        }
661	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
662	        // The household is deterministically keyed on (normalized last name, postcode): every owner
663	        // with a postcode belongs to the household identified by this computed id, and owners sharing
664	        // a last name and postcode share it automatically. A new owner may join an existing household;
665	        // the household ceiling below (rather than a hard rejection) governs its membership level.
666	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
667	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
668	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
669	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
670	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
671	        boolean identityInUse = this.clinicService.findAllOwners().stream()
672	            .filter(existing -> !existing.isDeleted())
673	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
674	                existing.getEmail(), existing.getLastName()).equals(identityKey));
675	        if (identityInUse) {
676	            return new ResponseEntity<>(HttpStatus.CONFLICT);
677	        }
678	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
679	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
680	        // duplicate, but the new owner is flagged as a possible duplicate of it.
681	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
682	        Integer possibleDuplicateOf = (postcode == null) ? null
683	            : this.clinicService.findAllOwners().stream()
684	                .filter(existing -> !existing.isDeleted())
685	                .filter(existing -> postcode.equals(existing.getPostcode()))
686	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
687	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
688	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
689	                .map(Owner::getId)
690	                .findFirst()
691	                .orElse(null);
692	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
693	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
694	            .filter(existing ->
695	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
696	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
697	            .count();
698	        HttpHeaders headers = new HttpHeaders();
699	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
700	        owner.setNamesakeCount(namesakeCount);
701	        owner.setAddress(address);
702	        if (structuredAddress) {
703	            owner.setAddressLine1(addressLine1);
704	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
705	        } else {
706	            owner.setAddressLine1(null);
707	            owner.setAddressLine2(null);
708	        }
709	        owner.setTelephone(telephone);
710	        owner.setEmail(email == null ? null : email.toLowerCase());
711	        owner.setRegistrationDate(registrationDate);
712	        owner.setMemberId(deduplicateMemberId(nextMemberId(
713	            region(postcode, owner.getCity()), registrationDate, telephone, owner.getLastName())));
714	        owner.setHouseholdId(householdId);
715	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
716	        this.clinicService.saveOwner(owner);
717	        if (idempotencyKey != null) {
718	            this.idempotentCreations.put(idempotencyKey, owner.getId());
719	        }
720	        owner.setHouseholdSize(householdSize(owner));
721	        Integer membershipLevel = cappedMembershipLevel(owner);
722	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
723	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
724	        // Immutable structured event carrying the owner's current primary identifier (the
725	        // unified memberId), with a monotonic sequence.
726	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
727	            owner.getMemberId(), membershipLevel).toJson());
728	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
729	        NOTIFY.info("welcome notification: ownerId={} memberId={}",
730	            owner.getId(), owner.getMemberId());
731	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
732	        ownerDto.setMembershipLevel(membershipLevel);
733	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
734	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
735	        headers.setLocation(UriComponentsBuilder.newInstance()
736	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
737	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
738	    }
739	
740	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
741	    @Override
742	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
743	        String telephone = toE164(ownerFieldsDto.getTelephone());
744	        if (telephone == null) {
745	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
746	        }
747	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
748	        if (currentOwner == null) {
749	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
750	        }
751	        String email = ownerFieldsDto.getEmail();
752	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
753	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
754	        }
755	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
756	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
757	        if (!addressLine1.isEmpty()) {
758	            currentOwner.setAddressLine1(addressLine1);
759	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
760	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
761	        } else {
762	            currentOwner.setAddressLine1(null);
763	            currentOwner.setAddressLine2(null);
764	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
765	        }
766	        currentOwner.setCity(ownerFieldsDto.getCity());
767	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
768	        currentOwner.setLastName(ownerFieldsDto.getLastName());
769	        currentOwner.setTelephone(telephone);
770	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
771	        this.clinicService.saveOwner(currentOwner);
772	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
773	    }
